import{z as s,x as A,o as e,c as l,q as r,j as o,D as E,d as i,s as n,S as B}from"./chunks/framework.C8m1ZpeB.js";const b=JSON.parse('{"title":"篮子与彩虹","description":"","frontmatter":{"title":"篮子与彩虹","date":"2026-09-08T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/basket-rainbow.md","filePath":"quant/basket-rainbow.md","lastUpdated":1791413859000}'),m={name:"quant/basket-rainbow.md"};function p(h,a,u,_,d,f){const t=A("Mermaid");return e(),l("div",null,[a[2]||(a[2]=r('<h1 id="篮子与彩虹" tabindex="-1">篮子与彩虹 <a class="header-anchor" href="#篮子与彩虹" aria-label="Permalink to &quot;篮子与彩虹&quot;">​</a></h1><div class="epigraph"><p>交换期权的执行价是另一资产的未来价格；彩虹把支付写在最好或最差的那一个上。一维反射用不上，相关结构成为一等公民。</p><footer>—— Margrabe, The Value of an Option to Exchange One Asset for Another, Journal of Finance, 1978；Stulz, Options on the Minimum or the Maximum of Two Risky Assets, Journal of Financial Economics, 1982</footer></div><p><a href="/quant/barrier-analytics">上一课</a>还在单资产路径与壁。本课把标的换成<strong>向量</strong>：篮子是加权和上的期权，彩虹是 \\(\\max\\) 或 \\(\\min\\) 上的期权，交换是 Margrabe 的 \\(S^{(1)}\\) 换 \\(S^{(2)}\\)。缺口是相关——不是再写一遍 <a href="/quant/bsm">BSM</a>，而是：<strong>多维对数正态下哪些有闭式，其余如何把相关从香草微笑里拆出来。</strong> 后课 quanto 再把外汇乘进来。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>篮子看涨 \\(\\bigl(\\sum w_i S_T^{(i)}-K\\bigr)^+\\) 没有闭式：和不是对数正态。彩虹 \\(\\bigl(\\max_i S_T^{(i)}-K\\bigr)^+\\) 在两资产、GBM、常数相关下有 Stulz 公式；三资产以上迅速变成高维正态积分。问题是报价台常用「篮子隐波」一个数去套 Black，这个数同时吸收了成分波动、权重、相关与微笑，<strong>不能</strong>拿去当相关互换的输入。</p><p>相关上升时，正权重篮子的方差 \\(\\mathbf{w}^\\top\\Sigma\\mathbf{w}\\) 上升，篮子期权变贵；「最好那个」的彩虹在相关下降时更贵，因为更能挑到跑赢的一个。符号可以相反。把篮子和彩虹都叫「多资产期权」然后共用一张相关矩阵去调，会把对冲方向做反。</p><p><span class="marginnote">术语翻译：篮子期权押的是「一锅汤」——一篮子资产按权重加起来的总和涨没涨过执行价；彩虹期权押的是「赛马」——只看跑得最好（best-of）或跑得最差（worst-of）的那一匹。前者关心总和，后者关心排序，所以相关性的作用方向可以完全相反。</span></p><p>\\(\\rho\\) 上升时各支付的价值方向：</p>',8)),(e(),o(B,null,{default:E(()=>[n(t,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20Q%5B%22%E9%97%AE%E9%A2%98%3A%20rho%20%E4%B8%8A%E5%8D%87%2C%20%E6%94%AF%E4%BB%98%E4%BB%B7%E5%80%BC%E5%90%91%E5%93%AA%E8%BE%B9%E8%B5%B0%3F%22%5D%20--%3E%20A%5B%22%E6%AD%A3%E6%9D%83%E9%87%8D%E7%AF%AE%E5%AD%90%E7%9C%8B%E6%B6%A8%22%5D%0A%20%20Q%20--%3E%20B%5B%22best-of%20%2F%20max%20%E5%BD%A9%E8%99%B9%22%5D%0A%20%20Q%20--%3E%20C%5B%22worst-of%20%E5%BD%A9%E8%99%B9%22%5D%0A%20%20A%20--%3E%20A1%5B%22%E7%BB%84%E5%90%88%E6%96%B9%E5%B7%AE%E5%8F%98%E5%A4%A7%3A%20%E6%9B%B4%E8%B4%B5%22%5D%0A%20%20B%20--%3E%20B1%5B%22%E8%B5%84%E4%BA%A7%E5%90%8C%E6%B6%A8%E5%90%8C%E8%B7%8C%2C%20%E6%8C%91%E9%80%89%E6%9D%83%E8%B4%AC%E5%80%BC%3A%20%E6%9B%B4%E4%BE%BF%E5%AE%9C%22%5D%0A%20%20C%20--%3E%20C1%5B%22%E7%9C%8B%E6%B6%A8%E6%9B%B4%E8%B4%B5%2C%20%E7%9C%8B%E8%B7%8C%E6%9B%B4%E4%BE%BF%E5%AE%9C%22%5D%0A%20%20C1%20--%3E%20N%5B%22%E7%AC%A6%E5%8F%B7%E5%BF%85%E9%A1%BB%E6%8C%89%E6%94%AF%E4%BB%98%E9%80%90%E4%B8%AA%E6%8E%A8%2C%20%E4%B8%8D%E8%83%BD%E5%A5%97%E3%80%8C%E5%A4%9A%E8%B5%84%E4%BA%A7%E3%80%8D%E6%A0%87%E7%AD%BE%22%5D%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[i(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=r('<h3 id="margrabe-是相对价格上的一维问题" tabindex="-1">Margrabe 是相对价格上的一维问题 <a class="header-anchor" href="#margrabe-是相对价格上的一维问题" aria-label="Permalink to &quot;Margrabe 是相对价格上的一维问题&quot;">​</a></h3><p>交换期权支付 \\((S_T^{(1)}-S_T^{(2)})^+\\)。以 \\(S^{(2)}\\) 为计价，相对价格 \\(S^{(1)}/S^{(2)}\\) 在 GBM 下仍是 GBM，波动是 \\(\\sqrt{\\sigma_1^2+\\sigma_2^2-2\\rho\\sigma_1\\sigma_2}\\)，执行价为 1。闭式存在是因为降维，不是因为「两资产比较简单」。一旦有微笑、有三个以上资产、或支付是篮子加权，降维消失。</p><p><span class="marginnote">指数期权在定义上是篮子期权，但指数有自己的期权市场。用成分香草加相关去复制指数期权，剩下的是相关风险溢价与分红差异，对象与 <a href="/quant/index-arb">指数套利</a> 相邻，本课不重写指数复制。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>两资产交换、两资产彩虹：闭式或低维积分，相关用历史或从指数/成分隐含相关反推。篮子：矩匹配（把 \\(\\sum w_i S_i\\) 配成一个对数正态）、Monte Carlo、或对加权和做近似分布（Milevsky–Posner 等）。有微笑时，每个成分用自己的边际（<a href="/quant/dupire">Dupire</a> 或混合对数正态），相关用高斯/t copula 或因子结构；边际与相关必须分开校准，见主干 <a href="/quant/copula">Copula</a>。</p><p>隐含相关：从指数期权与成分期权反推一个 \\(\\rho_{\\mathrm{imp}}\\)。它是定价核下的相关，不是已实现相关。后课 <a href="/quant/correlation-swap">相关互换</a> 交易这个差；<a href="/quant/dispersion-trade">分散交易</a> 是期权实现。</p><p><span class="marginnote">数字实例：交换期权的波动 \\(\\sqrt{\\sigma_1^2+\\sigma_2^2-2\\rho\\sigma_1\\sigma_2}\\)，取 \\(\\sigma_1=\\sigma_2=30\\%\\)、\\(\\rho=0.3\\)，得 \\(\\sqrt{0.18-0.054}\\approx 35.5\\%\\)——比任何一条腿单独的波动都高。直观上，相关越低，两只资产越各走各的，相对价格晃得越厉害，交换期权越值钱。</span></p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>正权重篮子：\\(\\rho\\) 升则组合方差升，期权更贵。这与分散交易的符号一致——做空指数波动、做多成分波动，近似做空隐含相关。Max-彩虹：\\(\\rho\\) 降则「挑选权」更值钱；worst-of 则在 \\(\\rho\\) 降时更易碰到最差腿，看涨变便宜、看跌变贵。同一张 \\(\\rho\\) 的比较静态，在篮子与彩虹上可以反号，必须按支付写，不能按「多资产」三个字写。</p>',9)),(e(),o(B,null,{default:E(()=>[n(t,{id:"mermaid-50",class:"mermaid",graph:"flowchart%20TD%0A%20%20Exch%5B%22%E4%BA%A4%E6%8D%A2%E6%9C%9F%E6%9D%83%20Margrabe%20%E9%99%8D%E7%BB%B4%22%5D%20--%3E%20OneD%5B%22%E7%9B%B8%E5%AF%B9%E4%BB%B7%E6%A0%BC%E4%B8%8A%E7%9A%84%E4%B8%80%E7%BB%B4%20Black%22%5D%0A%20%20Bask%5B%22%E7%AF%AE%E5%AD%90%20%E5%8A%A0%E6%9D%83%E5%92%8C%22%5D%20--%3E%20NoCF%5B%22%E5%92%8C%E4%B8%8D%E6%98%AF%E5%AF%B9%E6%95%B0%E6%AD%A3%E6%80%81%22%5D%0A%20%20Rain%5B%22%E5%BD%A9%E8%99%B9%20max%20%E6%88%96%20min%22%5D%20--%3E%20Stulz%5B%22%E4%B8%A4%E8%B5%84%E4%BA%A7%E6%9C%89%20Stulz%20%E9%97%AD%E5%BC%8F%22%5D%0A%20%20Bask%20--%3E%20Rho%5B%22%E7%9B%B8%E5%85%B3%E7%9A%84%E7%AC%A6%E5%8F%B7%E5%8F%96%E5%86%B3%E4%BA%8E%E6%94%AF%E4%BB%98%22%5D%0A%20%20Rain%20--%3E%20Rho%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[i(" Loading... ",-1)])]),_:1})),a[4]||(a[4]=r('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>矩匹配在权重集中、短期限时够用；成分有跳、相关不稳定、worst-of 有许多腿时会系统性偏。局部波动重现各边际，不重现共跳；危机里相关冲向 1，篮子与指数期权的价差会瞬间消失，复制失败。权重若随价格漂移（价格加权指数），状态还要包括相对权重，不是常数 \\(w\\)。</p><p>不要用一个篮子隐波去对冲成分 Vega：那个数字不是可交易的相关。</p><p><span class="marginnote">常见误区：初学者容易以为「用平静时期的历史相关校准复制组合就够了」。危机里相关会冲向 1——所有资产一起跌，篮子与指数期权的价差瞬间消失，复制在最需要它的那天失效。相关是状态依赖的，不是常数参数。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>交换期权可降维；篮子一般无闭式；两资产彩虹有 Stulz 公式。</li><li>相关对篮子与对 max/min 彩虹的比较静态可以反号。</li><li>篮子隐波把波动、权重、相关捆在一起，不能当相关互换输入。</li><li>出处：Margrabe, <em>Journal of Finance</em>, 1978；Stulz, <em>JFE</em>, 1982；Milevsky and Posner, <em>Journal of Financial and Quantitative Analysis</em>, 1998。</li></ul>',6))])}const c=s(m,[["render",p]]);export{b as __pageData,c as default};
